export const SEGMENTS = ['Long Haul','Regional','Construction','Winter','Urban'] as const;
export const SERIES = ['Premium','Standard'] as const;
export const POSITIONS = [...new Set(FINDER_TIRES.map(t=>t.pos))].sort();
export const FEATURE_TAGS = [...new Set(FINDER_TIRES.flatMap(t=>t.tags))].filter(t=>!['M+S','3PMSF','SmartWay','ML'].includes(t)).sort();

function parseSize(s: string){
  let m = s.match(/^([\d.]+)\/(\d+)R([\d.]+)$/);
  if(m) return {width:m[1], ratio:m[2], rim:m[3]};
  m = s.match(/^([\d.]+)R([\d.]+)$/);
  if(m) return {width:m[1], ratio:null, rim:m[2]};
  return {width:null, ratio:null, rim:null};
}
function numSort(arr: string[]){ return arr.sort((a,b)=>parseFloat(a)-parseFloat(b)); }
const widthSet=new Set<string>(), ratioSet=new Set<string>(), rimSet=new Set<string>();
FINDER_TIRES.forEach(t=>t.sizes.forEach(sz=>{
  const p=parseSize(sz.size);
  if(p.width) widthSet.add(p.width);
  if(p.ratio) ratioSet.add(p.ratio);
  if(p.rim) rimSet.add(p.rim);
}));
export const SIZE_WIDTHS = numSort([...widthSet]);
export const SIZE_RATIOS = numSort([...ratioSet]);
export const SIZE_RIMS = numSort([...rimSet]);
export function parseTireSize(s: string){ return parseSize(s); }
